INSERT INTO campaign (id_campaign, id_pembuat, judul, deskripsi, kategori, target_nominal, periode_mulai, periode_selesai, provinsi, kota, latitude, longitude, kebutuhan, rincian_penggunaan_dana, status, alasan_penolakan, dana_terkumpul, tanggal_dibuat, tanggal_pengajuan, tanggal_verifikasi) VALUES
  ('luwu', 'u4', 'Luwu Flash Flood Response', 'The early-August flash flood damaged 640 homes across three districts. Fundraising has closed. The funds raised now pay for the second aid distribution and house repairs.', 'Disaster relief', 200000000, '2026-08-01', '2026-09-30', 'Sulawesi Selatan', 'Luwu Regency', -3.35, 120.25, '2,000 families receive food packages and 40 badly damaged homes are repaired.', '[{"uraian":"Food packages for 2,000 families","nominal":80000000},{"uraian":"Clean water and tanks","nominal":26000000},{"uraian":"Repairs for 40 homes","nominal":58000000},{"uraian":"School supplies for children","nominal":12400000}]', 'terpublikasi', NULL, 176400000, '2026-08-01 00:00:00', NULL, '2026-08-01 00:00:00'),
  ('surya', 'u5', 'Solar Power for Kambera Health Center', 'This health center still relies on a generator that runs 6 hours a day, so the vaccine fridge often shuts down at night. Funds go to an 8 kWp solar array and storage batteries.', 'Clean energy', 95000000, '2026-10-05', '2026-12-31', 'Nusa Tenggara Timur', 'Kambera, East Sumba', -9.65, 120.26, '24-hour power for the vaccine room, the delivery room, and night lighting.', '[{"uraian":"8 kWp solar panels","nominal":52000000},{"uraian":"Batteries and inverter","nominal":33000000},{"uraian":"Installation and technician training","nominal":10000000}]', 'terpublikasi', NULL, 22800000, '2026-10-05 00:00:00', NULL, '2026-10-05 00:00:00'),
  ('enggros', 'u5', 'Enggros Village Infiltration Wells', 'Residents of this stilt village struggle to find fresh water in the dry season. Funds go to 20 infiltration wells and rainwater tanks on the nearest land.', 'Clean water', 50000000, '2026-10-01', '2027-01-15', 'Papua', 'Abepura, Jayapura City', -2.62, 140.75, '20 infiltration wells and 10 rainwater tanks serving 120 families.', '[{"uraian":"Infiltration wells (20)","nominal":30000000},{"uraian":"Rainwater tanks (10)","nominal":15000000},{"uraian":"Maintenance training","nominal":5000000}]', 'terpublikasi', NULL, 12000000, '2026-10-01 00:00:00', NULL, '2026-10-01 00:00:00'),
  ('lewotobi', 'u4', 'Water and Masks for Lewotobi Evacuees', 'About 3,000 evacuees in 4 shelters need clean water and N95 masks while volcanic ash keeps falling.', 'Disaster relief', 75000000, '2026-10-27', '2026-12-10', 'Nusa Tenggara Timur', 'Wulanggitang, East Flores', -8.53, 122.78, '20 liters of clean water per person per day and 10,000 masks for 6 weeks.', '[{"uraian":"Water tanker trucks for 6 weeks","nominal":45000000},{"uraian":"N95 masks (10,000)","nominal":22000000},{"uraian":"Distribution","nominal":8000000}]', 'menunggu_verifikasi', NULL, 0, '2026-10-27 00:00:00', '2026-10-25 09:12:00', NULL),
  ('tamankali', 'u2', 'Semarang Riverside Pocket Park', 'A strip of the Semarang River bank near Johar Market will become a small park with shade trees and benches.', 'Urban greening', 60000000, '2026-11-01', '2027-01-31', 'Jawa Tengah', 'Central Semarang', -6.98, 110.42, 'An 800 m² park open to the public.', NULL, 'ditolak', 'The fund-use breakdown is missing. Add the cost split for seedlings, tools, and labor, then submit again.', 0, '2026-11-01 00:00:00', '2026-10-12 10:00:00', '2026-10-14 15:30:00');
INSERT INTO project (id_project, id_pembuat, nama, deskripsi, tujuan, kategori, provinsi, kota, latitude, longitude, kebutuhan_dana, kebutuhan_logistik, kriteria_volunteer, rincian_penggunaan_dana, kuota_relawan, status_pendaftaran_project, jadwal_mulai, jadwal_selesai, lokasi_kumpul, status, alasan_penolakan, dana_terkumpul, milestone, status_pelaksanaan, timestamp_pembaruan, tanggal_dibuat, tanggal_pengajuan, tanggal_verifikasi) VALUES
  ('mgv', 'u2', 'Sayung Coastal Mangrove Restoration', 'Coastal erosion has swallowed hundreds of meters of the Sayung shoreline, and some homes now flood at every high tide. We are planting 12,000 Rhizophora mangrove seedlings along a 1.2 km belt, protected by bamboo wave breakers so the seedlings are not washed away.', '12,000 seedlings planted and 1.2 km of bamboo wave breakers installed before the west monsoon in mid-December 2026.', 'Mangroves & coast', 'Jawa Tengah', 'Sayung, Demak', -6.93, 110.5, 85000000, '12,000 Rhizophora seedlings; 600 bamboo poles; 2 small boats; 40 pairs of rubber boots', 'Fieldwork in mud; Photo documentation; Seedling data entry; First aid', '[{"uraian":"Mangrove seedlings (12,000)","nominal":36000000},{"uraian":"Bamboo and rope for wave breakers","nominal":21000000},{"uraian":"Boat rental and seedling transport","nominal":12000000},{"uraian":"Meals and volunteer gear","nominal":11000000},{"uraian":"6-month monitoring","nominal":5000000}]', 40, 'dibuka', '2026-10-01', '2026-12-15', 'Bedono Village Hall, Sayung. Meet at 06:30 WIB.', 'terpublikasi', NULL, 61250000, 'Planting phase 1 complete', 'berjalan', '2026-10-21 16:20:00', '2026-10-01 00:00:00', NULL, '2026-10-01 00:00:00'),
  ('air', 'u4', 'Clean Water for Upper Citarum Villages', 'Three hamlets in Kertasari still take water from a river polluted by livestock waste. We are building 3 storage tanks, 2 km of pipe from a spring, and slow sand filters that residents can maintain themselves.', '180 households get clean water from public taps by January 2027.', 'Clean water', 'Jawa Barat', 'Kertasari, Bandung Regency', -7.2, 107.7, 120000000, '2 km HDPE pipe; 3 concrete tanks (5,000 L); Silica sand and gravel', 'Carpentry; Pipe installation; Training residents on filter care', '[{"uraian":"Pipes and fittings","nominal":42000000},{"uraian":"Storage tanks","nominal":33000000},{"uraian":"Slow sand filters","nominal":25000000},{"uraian":"Local builder wages","nominal":20000000}]', 15, 'dibuka', '2026-09-15', '2027-01-31', 'Cibeureum Village Office, Kertasari. 07:00 WIB.', 'terpublikasi', NULL, 47500000, '800 m pipe trench dug', 'berjalan', '2026-10-17 14:00:00', '2026-09-15 00:00:00', NULL, '2026-09-15 00:00:00'),
  ('teduh', 'u2', 'Tambaksari School Shade Corridor', 'Children at four primary schools walk on sidewalks with no shade while midday temperatures pass 35°C. We are planting 320 shade trees along the 2.4 km corridor that links these schools, together with students and parents.', '320 shade trees planted, each with a caretaker (students and neighborhood units) for the first 2 years.', 'Urban greening', 'Jawa Timur', 'Tambaksari, Surabaya', -7.25, 112.75, 40000000, '320 tabebuia and ketapang kencana seedlings; 2 tons of manure; Stakes and tree guards', 'Planting and tree care; Supervising students; Documentation', '[{"uraian":"Tree seedlings (320)","nominal":16000000},{"uraian":"Steel tree guards","nominal":12000000},{"uraian":"Fertilizer and soil","nominal":5000000},{"uraian":"2-year maintenance","nominal":7000000}]', 30, 'dibuka', '2026-10-10', '2026-11-30', 'SDN Tambaksari 2 schoolyard. 06:00 WIB.', 'terpublikasi', NULL, 38900000, 'Project published', 'persiapan', '2026-10-10 09:00:00', '2026-10-10 00:00:00', NULL, '2026-10-10 00:00:00'),
  ('gambut', 'u5', 'Pulang Pisau Peatland Recovery', 'This 25-hectare peatland burned in 2023. We are blocking 6 canals so the peat becomes wet again, then planting 9,000 jelutung and belangeran seedlings with the local farmers group.', '6 canal blocks built and 9,000 seedlings planted before the 2027 dry season.', 'Reforestation', 'Kalimantan Tengah', 'Kahayan Hilir, Pulang Pisau', -2.75, 114.2, 150000000, '9,000 jelutung and belangeran seedlings; Galam timber for canal blocks; Portable water pump', 'Heavy fieldwork; GPS data collection; Cooking for the team', '[{"uraian":"Seedlings (9,000)","nominal":45000000},{"uraian":"Canal blocks (6 sites)","nominal":60000000},{"uraian":"Volunteer logistics","nominal":25000000},{"uraian":"Fire patrol for 1 year","nominal":20000000}]', 25, 'dibuka', '2026-09-01', '2027-03-31', 'Gohong Village post, Kahayan Hilir.', 'terpublikasi', NULL, 58000000, '2 canal blocks finished', 'berjalan', '2026-10-03 10:00:00', '2026-09-01 00:00:00', NULL, '2026-09-01 00:00:00'),
  ('subak', 'u4', 'Jatiluwih Subak Water Conservation', 'Water flow to the subak rice fields has dropped as the upstream forest thins. We are planting 2,500 trees around the springs and repairing 4 water tunnels with the subak leaders.', 'Dry-season flow at the subak weir back above 40 liters per second.', 'Clean water', 'Bali', 'Penebel, Tabanan', -8.37, 115.13, 60000000, '2,500 banyan, sugar palm, and bamboo seedlings; Cement and sand for tunnels', 'Planting; Water flow survey; English for guiding', '[{"uraian":"Tree seedlings (2,500)","nominal":20000000},{"uraian":"Water tunnel repairs","nominal":28000000},{"uraian":"Flow meters","nominal":6000000},{"uraian":"Volunteer meals","nominal":6000000}]', 20, 'dibuka', '2026-08-20', '2026-12-20', 'Jatiluwih Village Hall. 07:00 WITA.', 'terpublikasi', NULL, 41000000, 'Tunnels 1 and 2 repaired', 'berjalan', '2026-10-15 13:15:00', '2026-08-20 00:00:00', NULL, '2026-08-20 00:00:00'),
  ('sampah', 'u5', 'Galala Coastal Waste Bank', 'Plastic waste from the Galala coastal village drifts into the bay. We are opening a community waste bank with scales, a warehouse, and a steady buyer for recyclable plastic.', '1 ton of plastic per month kept out of the sea, with residents earning savings from what they bring in.', 'Waste & recycling', 'Maluku', 'Sirimau, Ambon City', -3.69, 128.18, 35000000, 'Digital scale; 4x6 m warehouse; Sacks and sorting racks', 'Record keeping; Community outreach; Sorting waste', '[{"uraian":"Warehouse and racks","nominal":15000000},{"uraian":"Scale and sorting tools","nominal":8000000},{"uraian":"Committee training","nominal":7000000},{"uraian":"Starting savings fund","nominal":5000000}]', 12, 'dibuka', '2026-10-15', '2027-02-28', 'RW 03 community hall, Galala. 15:00 WIT.', 'terpublikasi', NULL, 9500000, 'Project published', 'persiapan', '2026-10-15 08:00:00', '2026-10-15 00:00:00', NULL, '2026-10-15 00:00:00'),
  ('leuser', 'u4', 'Leuser Forest Replanting', '18 hectares of former illegal plantation at the edge of Gunung Leuser National Park were replanted with native forest trees together with buffer-zone communities.', '18 hectares planted with 7,200 native trees.', 'Reforestation', 'Aceh', 'Blangkejeren, Gayo Lues', 3.95, 97.35, 70000000, '7,200 native tree seedlings', 'Planting; GPS data collection', '[{"uraian":"Seedlings (7,200)","nominal":30000000},{"uraian":"Local planter wages","nominal":22000000},{"uraian":"Logistics and transport","nominal":12000000},{"uraian":"Monitoring","nominal":6000000}]', 30, 'ditutup', '2026-03-01', '2026-08-31', 'Blangkejeren ranger office.', 'terpublikasi', NULL, 70000000, 'Final report', 'selesai', '2026-08-31 17:00:00', '2026-03-01 00:00:00', NULL, '2026-03-01 00:00:00'),
  ('biopori', 'u2', 'Lempongsari Biopore Drive', 'The alleys of Lempongsari flood during heavy rain. Together with residents we are making 400 biopore holes and 12 infiltration wells.', '400 biopore holes and 12 infiltration wells across 6 neighborhood units.', 'Urban greening', 'Jawa Tengah', 'Gajahmungkur, Semarang City', -7.02, 110.41, 15000000, '10 biopore augers; 4-inch PVC pipe', 'Light physical work; Community outreach', '[{"uraian":"Augers and pipes","nominal":7000000},{"uraian":"Infiltration wells (12)","nominal":6000000},{"uraian":"Meals for work days","nominal":2000000}]', 10, 'dibuka', '2026-10-20', '2026-12-31', 'RW 05 hall, Lempongsari. 07:00 WIB.', 'terpublikasi', NULL, 3200000, 'Project published', 'persiapan', '2026-10-20 09:00:00', '2026-10-20 00:00:00', NULL, '2026-10-20 00:00:00'),
  ('rusun', 'u5', 'Marunda Rooftop Food Gardens', 'The rooftops of 3 public housing blocks will become hydroponic vegetable gardens run by residents. The harvest will be sold to nearby food stalls.', '3 active rooftop gardens harvesting every 30 days.', 'Urban greening', 'DKI Jakarta', 'Cilincing, North Jakarta', -6.1, 106.95, 28000000, '30 hydroponic racks; 3 water tanks; Seeds and nutrients', 'Hydroponics; Basic bookkeeping', '[{"uraian":"Hydroponic racks and pipes","nominal":15000000},{"uraian":"Tanks and pumps","nominal":7000000},{"uraian":"Seeds and nutrients for 6 months","nominal":6000000}]', 15, 'dibuka', '2026-11-15', '2027-02-28', 'Block C lobby, Marunda housing.', 'menunggu_verifikasi', NULL, 0, NULL, 'persiapan', NULL, '2026-11-15 00:00:00', '2026-10-24 13:40:00', NULL);
