  ('PRG-mgv-1', 'mgv', 'u2', 'Project published', 'persiapan', 'The project passed review and is now open for donations and volunteer sign-ups.', 0, 0, NULL, '2026-10-01 08:00:00'),
  ('PRG-mgv-2', 'mgv', 'u2', '400 m of bamboo breakers installed', 'berjalan', 'The first wave breaker section is up. Water behind it has calmed and sediment is starting to settle.', 18, 9800000, 'breaker-400m.jpg', '2026-10-08 10:05:00'),
  ('PRG-mgv-3', 'mgv', 'u2', 'Planting phase 1 complete', 'berjalan', '31 volunteers planted 4,200 seedlings in plots A and B. Survival rate after the first week: 94%.', 35, 24500000, 'plots-a-b.jpg, attendance.pdf', '2026-10-21 16:20:00'),
  ('PRG-air-1', 'air', 'u4', 'Project published', 'persiapan', 'The project passed review.', 0, 0, NULL, '2026-09-15 09:00:00'),
  ('PRG-air-2', 'air', 'u4', '800 m pipe trench dug', 'berjalan', 'The pipe trench from the Cikahuripan spring now runs 800 meters. Pipe laying starts next week.', 30, 21000000, 'trench-800m.jpg', '2026-10-17 14:00:00'),
  ('PRG-teduh-1', 'teduh', 'u2', 'Project published', 'persiapan', 'The project passed review. Planting spots are agreed with the sub-district office.', 0, 0, 'planting-map.pdf', '2026-10-10 09:00:00'),
  ('PRG-gambut-1', 'gambut', 'u5', '2 canal blocks finished', 'berjalan', 'The water table in the northern block rose 30 cm in two weeks.', 22, 31000000, 'blocks-1-2.jpg', '2026-10-03 10:00:00'),
  ('PRG-subak-1', 'subak', 'u4', 'Tunnels 1 and 2 repaired', 'berjalan', 'Leaks in two tunnels are sealed. About 6 more liters per second now reach the fields.', 40, 19000000, 'tunnels.jpg', '2026-10-15 13:15:00'),
  ('PRG-sampah-1', 'sampah', 'u5', 'Project published', 'persiapan', 'The project passed review. Residents donated the warehouse site.', 0, 0, NULL, '2026-10-15 08:00:00'),
  ('PRG-leuser-1', 'leuser', 'u4', 'Project published', 'persiapan', 'The project passed review.', 0, 0, NULL, '2026-03-01 08:00:00'),
  ('PRG-leuser-2', 'leuser', 'u4', 'Planting phases 1 and 2', 'berjalan', '3,300 trees planted in blocks A and B.', 45, 31000000, NULL, '2026-04-28 10:00:00'),
  ('PRG-leuser-3', 'leuser', 'u4', 'Planting phase 3 complete', 'berjalan', '5,800 trees planted in total.', 80, 56000000, 'phase-3.jpg', '2026-06-20 10:00:00'),
  ('PRG-leuser-4', 'leuser', 'u4', 'Final report', 'selesai', '7,200 trees planted. Survival rate after 3 months: 87%. Full fund-use report attached.', 100, 70000000, 'final-report.pdf, aerial-photo.jpg', '2026-08-31 17:00:00'),
